    harness.put("acyclic.harness.v2.HarnessService/Cancel", new Operation(false, false, true, "operation", List.of("operation:cancel"), List.of("ERROR_CODE_UNSPECIFIED", "ERROR_CODE_NOT_FOUND", "ERROR_CODE_CONFLICT", "ERROR_CODE_UNSUPPORTED", "ERROR_CODE_INVALID", "ERROR_CODE_UNAUTHORIZED", "ERROR_CODE_STORAGE", "ERROR_CODE_INDETERMINATE", "ERROR_CODE_INTERACTION_DECLINED", "ERROR_CODE_INTERACTION_CANCELLED", "ERROR_CODE_INTERACTION_EXPIRED", "ERROR_CODE_INTERACTION_DENIED"), List.of("protocol.identity.exact", "owner.required", "operation_id.nonempty", "idempotency_key.nonempty", "scope.required", "scope.capability.operation_cancel", "status.identity.matches")));
